mapper.select:
SELECT club_id AS clubId ,club_name AS clubName ,c.sport_id AS sportId ,c.recruit_status AS recruitStatus ,c.max_members AS maxMembers ,c.activity_days AS activityDays ,c.activity_start_time AS activityStartTime ,c.activity_end_time AS activityEndTime ,c.created_at AS createdAt ,s.name AS sportName ,(SELECT COUNT(*) FROM club_member m where m.club_id = c.club_id AND m.left_at IS NULL) AS memberCount , AS averageMmr ,(SELECT GROUP_CONCAT(rg.name ORDER BY rg.region_id SEPARATOR ', ') FROM club_region cr JOIN region rg ON cr.region_id = rg.region_id WHERE cr.club_id = c.club_id) AS areaLabel FROM club c JOIN sport s ON c.sport_id = s.sport_id WHERE c.deleted_at IS NULL
AND (c.club_name LIKE CONCAT('%', #{likeQuery}, '%') ESCAPE '!' OR EXISTS (SELECT 1 FROM club_region qr JOIN region qrg ON qr.region_id = qrg.region_id WHERE qr.club_id = c.club_id AND qrg.name LIKE CONCAT('%', #{likeQuery}, '%') ESCAPE '!'))
AND c.sport_id = #{sportId}
AND EXISTS (SELECT 1 FROM club_region r WHERE r.club_id = c.club_id AND r.region_id = #{regionId})
AND c.recruit_status = '모집중' AND (SELECT COUNT(*) FROM club_member m WHERE m.club_id = c.club_id AND m.left_at IS NULL) < c.max_members
AND >= #{minMmr}
AND < #{maxMmr}
ORDER BY averageMmr DESC, c.created_at DESC , DESC ,c.club_id DESC
ORDER BY DESC, c.created_at DESC ,averageMmr DESC ,c.club_id DESC
ORDER BY c.created_at DESC, averageMmr DESC , DESC ,c.club_id DESC

mapper.update:
UPDATE club_member SET role = '동호회장'
WHERE club_member_id = #{clubMemberId} AND club_id = #{clubId}
    AND role = '동호회원' AND left_at IS NULL

UPDATE club_member SET role = '동호회원'
WHERE club_id = #{clubId} AND user_id = #{userId}
    AND role = '동호회장' AND left_at IS NULL

UPDATE club_member
SET left_at = NOW(), leave_type = '내보내기', kick_reason = #{kickReason}
WHERE club_id = #{clubId} AND club_member_id = #{clubMemberId} 
    AND left_at IS NULL
